# Write CSV files with UTF-8 BOM for Excel
fields_master = ["대학명", "전형명", "전형구분", "모집인원", "지원자격", "1단계", "2단계", "최저학력기준", "면접고사일", "면접유형", "특이사항"]
fields_cal = ["일자", "요일", "수능전후", "대학명", "전형명", "계열_학과", "면접유형", "비고"]

def write_csv(filepath, fieldnames, data):
    with open(filepath, 'w', encoding='utf-8-sig', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)

def write_xls_html(filepath, title, headers, data, keys):
    rows_html = ""
    for r in data:
        tds = "".join([f"<td>{r[k]}</td>" for k in keys])
        rows_html += f"<tr>{tds}</tr>"
    ths = "".join([f"<th>{h}</th>" for h in headers])
    html_content = f"<html><head><meta charset='utf-8'></head><body><h2>{title}</h2><table border='1'><tr>{ths}</tr>{rows_html}</table></body></html>"
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(html_content)

# Export Master
write_csv(os.path.join(desktop_dir, "2027_학생부종합전형_통합DB.csv"), fields_master, master_data)
write_csv(os.path.join(workspace_dir, "2027_학생부종합전형_통합DB.csv"), fields_master, master_data)
write_xls_html(os.path.join(desktop_dir, "2027_학생부종합전형_통합DB.xls"), "2027 수도권 주요 대학 학생부 종합전형 통합 DB", fields_master, master_data, fields_master)
write_xls_html(os.path.join(workspace_dir, "2027_학생부종합전형_통합DB.xls"), "2027 수도권 주요 대학 학생부 종합전형 통합 DB", fields_master, master_data, fields_master)

